seen = []
class A:
    def __init__(self):
        seen.append(self)
a = A()
assert seen == [a] and seen[0] is a

class A:
    def __init__(self, v):
        self.v = v
    def __eq__(self, o):
        return self.v == o.v
x = [A(1), A(2)]
assert x.index(A(2)) == 1
assert x.count(A(1)) == 1
x.remove(A(2))
assert len(x) == 1
